code.value:
systime_t time = chVTGetSystemTimeX();
while (time == chVTGetSystemTimeX()) {
#if defined(SIMULATOR)
    _sim_check_for_interrupts();
#endif
}

bool b;

b = chTimeIsInRangeX((systime_t)0, (systime_t)0, (systime_t)0);
test_assert(b == false, "in range");
b = chTimeIsInRangeX((systime_t)-1, (systime_t)0, (systime_t)0);
test_assert(b == false, "in range");
b = chTimeIsInRangeX((systime_t)0, (systime_t)-1, (systime_t)-1);
test_assert(b == false, "in range");
b = chTimeIsInRangeX((systime_t)-1, (systime_t)-1, (systime_t)-1);
test_assert(b == false, "in range");

bool b;

b = chTimeIsInRangeX((systime_t)10, (systime_t)10, (systime_t)100);
test_assert(b == true, "not in range");
b = chTimeIsInRangeX((systime_t)9, (systime_t)10, (systime_t)100);
test_assert(b == false, "in range");
b = chTimeIsInRangeX((systime_t)99, (systime_t)10, (systime_t)100);
test_assert(b == true, "not in range");
b = chTimeIsInRangeX((systime_t)100, (systime_t)10, (systime_t)100);
test_assert(b == false, "in range");

bool b;

b = chTimeIsInRangeX((systime_t)100, (systime_t)100, (systime_t)10);
test_assert(b == true, "not in range");
b = chTimeIsInRangeX((systime_t)99, (systime_t)100, (systime_t)10);
test_assert(b == false, "in range");
b = chTimeIsInRangeX((systime_t)9, (systime_t)100, (systime_t)10);
test_assert(b == true, "not in range");
b = chTimeIsInRangeX((systime_t)10, (systime_t)100, (systime_t)10);
test_assert(b == false, "in range");

test_assert(tm1.best == (rtcnt_t)-1, "invalid best");
test_assert(tm1.worst == (rtcnt_t)0, "invalid worst");
test_assert(tm1.last == (rtcnt_t)0, "invalid last");
test_assert(tm1.n == (ucnt_t)0, "invalid counter");
test_assert(tm1.cumulative == (rttime_t)0, "invalid cumulative");

chTMStartMeasurementX(&tm1);
chSysPolledDelayX((rtcnt_t)100);
chTMStopMeasurementX(&tm1);

test_assert(tm1.n == (ucnt_t)1, "invalid counter");
test_assert(tm1.last > (rtcnt_t)0, "invalid last");
test_assert(tm1.best == tm1.last, "invalid best");
test_assert(tm1.worst == tm1.last, "invalid worst");
test_assert(tm1.cumulative == (rttime_t)tm1.last, "invalid cumulative");
first = tm1.last;

chTMChainMeasurementToX(&tm1, &tm2);
chSysPolledDelayX((rtcnt_t)10);
chTMStopMeasurementX(&tm2);

test_assert(tm1.n == (ucnt_t)2, "invalid counter");
test_assert(tm1.last > (rtcnt_t)0, "invalid last");
test_assert(tm1.best <= tm1.worst, "invalid range");
test_assert(tm1.cumulative >= (rttime_t)first, "invalid cumulative");
test_assert(tm2.n == (ucnt_t)1, "invalid counter");
test_assert(tm2.last > (rtcnt_t)0, "invalid last");
test_assert(tm2.best == tm2.last, "invalid best");
test_assert(tm2.worst == tm2.last, "invalid worst");

chSysLock();
chVTDoSetI(&timers_state_vt, TIME_INFINITE, timers_state_cb, NULL);
pending = chVTGetTimersStateI(&interval);
chVTDoResetI(&timers_state_vt);
chSysUnlock();

test_assert(pending, "timer not reported");
test_assert(interval > (TIME_MAX_INTERVAL / (sysinterval_t)2),
            "interval addition wrapped");

chSysLock();
chVTDoSetI(&timers_state_vt, currcore->vtlist.lastdelta,
           timers_state_cb, NULL);
do {
  interval = chTimeDiffX(currcore->vtlist.lasttime, chVTGetSystemTimeX());
} while (interval <= (timers_state_vt.dlist.delta +
                      currcore->vtlist.lastdelta));
pending = chVTGetTimersStateI(&interval);
chVTDoResetI(&timers_state_vt);
chSysUnlock();

test_assert(pending, "timer not reported");
test_assert(interval == (sysinterval_t)0, "interval subtraction wrapped");

chSysLock();
(void) chRFCUGetAndClearFaultsI(CH_RFCU_ALL_FAULTS);
chVTDoSetI(&timers_overflow_anchor, TIME_INFINITE,
           timers_state_cb, NULL);
do {
  nowdelta = chTimeDiffX(currcore->vtlist.lasttime,
                         chVTGetSystemTimeX());
} while (nowdelta < (sysinterval_t)2);
delay = TIME_INFINITE - nowdelta + (sysinterval_t)1;
chVTDoSetI(&timers_overflow_vt, delay, timers_state_cb, NULL);
mask = chRFCUGetAndClearFaultsI(CH_RFCU_ALL_FAULTS);
listdelta = timers_overflow_vt.dlist.delta;
chVTDoResetI(&timers_overflow_vt);
chVTDoResetI(&timers_overflow_anchor);
chSysUnlock();

test_assert((mask & CH_RFCU_VT_INTERVAL_OVERFLOW) != (rfcu_mask_t)0,
            "overflow fault not reported");
test_assert(listdelta == TIME_INFINITE,
            "list coordinate not saturated");

delta = chVTGetCurrentDelta();
test_assert(delta >= (sysinterval_t)CH_CFG_ST_TIMEDELTA,
            "invalid current delta");

systime_t start, end;
systimestamp_t last, now;
sysinterval_t duration;

last = chVTGetTimeStamp();
start = test_wait_tick();
duration = (sysinterval_t)(TIME_MAX_SYSTIME / 2U);
if (duration > TIME_MS2I(1000)) {
  duration = TIME_MS2I(1000);
}
end = chTimeAddX(start, duration);
do {
  now = chVTGetTimeStamp();
  test_assert(last <= now, "not monotonic");
  last = now;
#if defined(SIMULATOR)
  _sim_check_for_interrupts();
#endif
} while (chVTIsSystemTimeWithinX(start, end));

shared_code.value:
static THD_FUNCTION(thread, p) {

  test_emit_token(*(char *)p);
}

#if (CH_CFG_USE_MUTEXES == TRUE) || defined(__DOXYGEN__)
static MUTEX_DECL(priority_mtx);

static THD_FUNCTION(priority_thread, p) {

  (void)p;
  chMtxLock(&priority_mtx);
  chMtxUnlock(&priority_mtx);
}
#endif /* CH_CFG_USE_MUTEXES == TRUE */

static void setup_thread_descriptor(thread_descriptor_t *tdp,
                                    const char *name,
                                    stkline_t *wbase,
                                    stkline_t *wend,
                                    tprio_t prio,
                                    void *arg) {

  tdp->name  = name;
  tdp->wbase = wbase;
  tdp->wend  = wend;
  tdp->prio  = prio;
  tdp->funcp = thread;
  tdp->arg   = arg;
  tdp->owner = NULL;
}

#if ((CH_DBG_TRACE_MASK != CH_DBG_TRACE_MASK_DISABLED) &&                 \
     ((CH_DBG_TRACE_MASK & CH_DBG_TRACE_MASK_READY) != 0U) &&             \
     (CH_CFG_USE_WAITEXIT == TRUE)) || defined(__DOXYGEN__)
static bool find_ready_trace(thread_t *tp, tstate_t state, msg_t *msgp) {
  trace_buffer_t *tbp = &currcore->trace_buffer;
  trace_event_t *tep = tbp->ptr;
  unsigned i;

  for (i = 0U; i < (unsigned)CH_DBG_TRACE_BUFFER_SIZE; i++) {
    if (tep == &tbp->buffer[0]) {
      tep = &tbp->buffer[CH_DBG_TRACE_BUFFER_SIZE];
    }
    tep--;
    if ((tep->type == CH_TRACE_TYPE_READY) &&
        (tep->state == (uint8_t)state) &&
        (tep->u.rdy.tp == tp)) {
      *msgp = tep->u.rdy.msg;
      return true;
    }
  }

  return false;
}
#endif

