static THD_FUNCTION(msg_thread1, p) {

  chMsgSend(p, 'A');
  chMsgSend(p, 'B');
  chMsgSend(p, 'C');
  chMsgSend(p, 'D');
}

static THD_FUNCTION(msg_thread2, p) {
  msg_t msg;

  msg = chMsgSend(p, 'E');
  test_emit_token(msg);
}

static THD_FUNCTION(msg_thread3, p) {
  msg_t msg;

  chThdSleepMilliseconds(50);
  msg = chMsgSend(p, 'F');
  test_emit_token(msg);
}

typedef struct {
  thread_t *receiver;
  msg_t request;
  msg_t response;
  char token;
} msg_sender_args_t;

static msg_sender_args_t msg_sender_args[2];

static THD_FUNCTION(msg_lifecycle_sender, p) {
  msg_sender_args_t *ap = (msg_sender_args_t *)p;
  msg_t msg;

  msg = chMsgSend(ap->receiver, ap->request);
  if (msg == ap->response) {
    test_emit_token(ap->token);
  }
  else {
    test_emit_token('X');
  }
}

static THD_FUNCTION(msg_exit_thread, p) {

  (void)p;
}

static THD_FUNCTION(msg_release_all_thread, p) {

  (void)p;
  chSysLock();
  chMsgReleaseAllI();
  chThdExitS(MSG_OK);
}

static THD_FUNCTION(msg_release_all_after_wait, p) {
  thread_t *tp;

  (void)p;
  tp = chMsgWait();
  test_emit_token((char)chMsgGet(tp));
  chSysLock();
  chMsgReleaseAllI();
  chThdExitS(MSG_OK);
}

