                               test_thread, NULL);
test_wait_threads();

td.name   = "priority-low";
td.wbase  = TEST_THREAD_WA_BASE(0);
td.wend   = TEST_THREAD_WA_END(0);
td.prio   = LOWPRIO;
td.funcp  = test_thread;
td.arg    = NULL;
td.owner  = NULL;
threads[0] = chThdCreate(&td);
test_wait_threads();

td.name   = "priority-high";
td.wbase  = TEST_THREAD_STACK_BASE(0);
td.wend   = TEST_THREAD_STACK_END(0);
td.prio   = HIGHPRIO;
td.funcp  = test_thread;
td.arg    = NULL;
td.owner  = NULL;
threads[0] = chThdSpawnRunning(TEST_THREAD_OBJECT(0), &td);
test_wait_threads();
chThdObjectDispose(TEST_THREAD_OBJECT(0));

chMtxLock(&m1);
m1.cnt = MUTEX_MAX_RECURSION - (cnt_t)1;
chMtxLock(&m1);
test_assert(m1.cnt == MUTEX_MAX_RECURSION,
            "wrong recursion counter");
chMtxUnlockAll();

b = chMtxTryLock(&m1);
test_assert(b, "already locked");
m1.cnt = MUTEX_MAX_RECURSION - (cnt_t)1;
b = chMtxTryLock(&m1);
test_assert(b, "recursive lock failed");
test_assert(m1.cnt == MUTEX_MAX_RECURSION,
            "wrong recursion counter");
chMtxUnlockAll();

description.value:
@p chThdAddRef() reaches @p
                  THREAD_MAX_REFERENCES without overflowing the counter,
                  then the final object is disposed.

code.value:
td.name   = "reference-boundary";
td.wbase  = TEST_THREAD_STACK_BASE(0);
td.wend   = TEST_THREAD_STACK_END(0);
td.prio   = LOWPRIO;
td.funcp  = test_thread;
td.arg    = NULL;
td.owner  = NULL;
tp = chThdObjectInit(TEST_THREAD_OBJECT(0), &td);
tp->refs = THREAD_MAX_REFERENCES - (trefs_t)1;
test_assert(chThdAddRef(tp) == tp, "wrong thread reference");
test_assert(tp->refs == THREAD_MAX_REFERENCES,
            "wrong reference counter");
tp->refs = (trefs_t)0;
tp->state = CH_STATE_FINAL;
chThdObjectDispose(tp);
